const sharedCanvas = typeof document !== 'undefined' ? document.createElement('canvas') : null;
const sharedContext = sharedCanvas ? sharedCanvas.getContext('2d') : null;

installSmoothHorizontalScroll();

function installSmoothHorizontalScroll() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  if (window.__zaydanSmoothHorizontalScrollInstalled) return;
  window.__zaydanSmoothHorizontalScrollInstalled = true;

  const hasFinePointer = !window.matchMedia || window.matchMedia('(pointer: fine)').matches;
  if (!hasFinePointer) return;

  function start() {
    const track = document.getElementById('track');
    const scrollCapture = document.getElementById('scroll-capture');
    if (!track || !scrollCapture) {
      window.setTimeout(start, 80);
      return;
    }

    let maxX = window.innerWidth;
    let currentX = 0;
    let targetX = 0;
    let externalOwner = false;
    let lastTs = performance.now();
    let idleTimer = 0;

    track.style.willChange = 'transform';
    track.style.backfaceVisibility = 'hidden';

    function clampX(value) {
      return Math.max(0, Math.min(maxX, value));
    }

    function readTrackX() {
      const inlineTransform = track.style.transform || '';
      let match = inlineTransform.match(/translate3d\((-?[\d.]+)px/i);
      if (match) return clampX(-(parseFloat(match[1]) || 0));

      const computedTransform = window.getComputedStyle(track).transform;
      match = computedTransform && computedTransform.match(/^matrix\((.+)\)$/);
      if (match) {
        const parts = match[1].split(',').map(parseFloat);
        if (parts.length >= 6) return clampX(-(parts[4] || 0));
      }
      return 0;
    }

    function normalizeWheelDelta(event) {
      let delta = event.deltaY + event.deltaX;
      if (event.deltaMode === 1) delta *= 18;
      else if (event.deltaMode === 2) delta *= window.innerHeight;
      return delta;
    }

    function markExternalInput() {
      externalOwner = true;
      document.body.classList.add('horizontal-scroll-active');
      window.clearTimeout(idleTimer);
      idleTimer = window.setTimeout(function () {
        document.body.classList.remove('horizontal-scroll-active');
      }, 180);
    }

    function moveBy(delta) {
      if (!delta) return;
      targetX = clampX(targetX + delta);
      markExternalInput();
    }

    function handleWheel(event) {
      if (event.ctrlKey) return;
      const delta = normalizeWheelDelta(event);
      if (!delta) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      moveBy(delta * 1.08);
    }

    function handleKeydown(event) {
      const tag = event.target && event.target.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      const delta = {
        ArrowDown: 240,
        ArrowRight: 240,
        PageDown: maxX,
        ArrowUp: -240,
        ArrowLeft: -240,
        PageUp: -maxX
      }[event.key];
      if (!delta) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      moveBy(delta);
    }

    window.addEventListener('resize', function () {
      maxX = window.innerWidth;
      targetX = targetX > maxX / 2 ? maxX : 0;
      currentX = clampX(currentX);
    }, { passive: true });

    document.addEventListener('wheel', handleWheel, { capture: true, passive: false });
    document.addEventListener('keydown', handleKeydown, { capture: true });

    function animate(ts) {
      const dt = Math.min(0.05, Math.max(0.001, (ts - lastTs) / 1000 || 0.016));
      lastTs = ts;

      if (!externalOwner) {
        const observedX = readTrackX();
        currentX = observedX;
        targetX = observedX;
      } else {
        const ease = 1 - Math.exp(-dt * 22);
        currentX += (targetX - currentX) * ease;
        if (Math.abs(targetX - currentX) < 0.18) currentX = targetX;
        if (currentX === 0 && targetX === 0) externalOwner = false;
      }

      track.style.transform = 'translate3d(-' + currentX.toFixed(2) + 'px,0,0)';
      window.requestAnimationFrame(animate);
    }

    currentX = readTrackX();
    targetX = currentX;
    window.requestAnimationFrame(animate);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
  else start();
}

export function prepareWithSegments(value, font) {
  if (font && /'Georgia',serif/.test(font)) {
    throw new Error('Use the animated monospace renderer for first-panel ASCII.');
  }

  const text = String(value || '');
  const segments = Array.from(text);
  const widths = [];

  if (sharedContext) {
    sharedContext.font = font || '16px serif';
    for (const segment of segments) {
      widths.push(sharedContext.measureText(segment).width);
    }
  } else {
    for (const segment of segments) {
      widths.push(segment === ' ' ? 4 : 8);
    }
  }

  return { segments, widths };
}
